${pagingTop} SELECT , (SELECT COUNT(*) FROM BOOK_PACKAGE_LOAN WHERE book_package_idx = a.book_package_idx AND request_status IN (0, 1, 2)) AS lender_count FROM BOOK_PACKAGE a
AND ${search_type} LIKE '%'||#{search_text}||'%'
AND REGEXP_LIKE(category, REPLACE(#{category}, ',', '|'))
AND grade = #{grade}
AND #{lender_count}
= <=
(SELECT COUNT(*) FROM BOOK_PACKAGE_LOAN WHERE book_package_idx = a.book_package_idx AND request_status IN (0, 1, 2))
ORDER BY book_package_idx DESC ${pagingBottom}

${pagingTop}
SELECT
	b.book_package_idx, b.book_package_loan_idx, a.book_package_subject, b.request_name, b.school_name,
	a.quantity, a.loan_count,
	TO_CHAR(b.loan_start_date, 'yyyy-MM-dd') AS loan_start_date, TO_CHAR(b.loan_end_date, 'yyyy-MM-dd') AS loan_end_date,
	b.phone, b.school_tel, b.request_content, b.request_status, b.return_yn,
	b.add_id, b.add_date
FROM
	BOOK_PACKAGE a, BOOK_PACKAGE_LOAN b
WHERE
	a.book_package_idx = b.book_package_idx

AND	${search_type} LIKE '%'||#{search_text}||'%'


	
	AND	return_yn = #{return_yn}
	AND	request_status = '2'
	
	
	AND	request_status = #{request_status}
	


AND	TO_CHAR(loan_start_date, 'yyyy') = #{loan_start_date}


AND b.add_id = #{add_id}

ORDER BY b.book_package_loan_idx DESC
${pagingBottom}

SELECT
	COUNT(*)
FROM
	BOOK_PACKAGE a, BOOK_PACKAGE_LOAN b
WHERE
	a.book_package_idx = b.book_package_idx

AND	${search_type} LIKE '%'||#{search_text}||'%'


	
	AND	return_yn = #{return_yn}
	AND	request_status = '2'
	
	
	AND	request_status = #{request_status}
	


AND	TO_CHAR(loan_start_date, 'yyyy') = #{loan_start_date}


AND b.add_id = #{add_id}

